22	int gc2083_i2c_init(VI_PIPE ViPipe)
23	{
24		char acDevFile[16] = {0};
25		CVI_U8 u8DevNum;
26	
27		if (g_fd[ViPipe] >= 0)
28			return CVI_SUCCESS;
29		int ret;
30	
31		u8DevNum = g_aunGc2083_BusInfo[ViPipe].s8I2cDev;
32		snprintf(acDevFile, sizeof(acDevFile),  "/dev/i2c-%u", u8DevNum);
33	
34		g_fd[ViPipe] = open(acDevFile, O_RDWR, 0600);
35	
36		if (g_fd[ViPipe] < 0) {
37			CVI_TRACE_SNS(CVI_DBG_ERR, "Open /dev/i2c-%u error!\n", u8DevNum);
38			return CVI_FAILURE;
39		}
40	
41		ret = ioctl(g_fd[ViPipe], I2C_SLAVE_FORCE, gc2083_i2c_addr);
42		if (ret < 0) {
43			CVI_TRACE_SNS(CVI_DBG_ERR, "I2C_SLAVE_FORCE error!\n");
44			close(g_fd[ViPipe]);
45			g_fd[ViPipe] = -1;
46			return ret;
47		}
48	
49		return CVI_SUCCESS;
50	}
