104	int gc2083_write_register(VI_PIPE ViPipe, int addr, int data)
105	{
106		CVI_U8 idx = 0;
107		int ret;
108		CVI_U8 buf[8];
109	
110		if (g_fd[ViPipe] < 0)
111			return CVI_SUCCESS;
112	
113		if (gc2083_addr_byte == 2) {
114			buf[idx] = (addr >> 8) & 0xff;
115			idx++;
116			buf[idx] = addr & 0xff;
117			idx++;
118		}
119		if (gc2083_data_byte == 1) {
120			buf[idx] = data & 0xff;
121			idx++;
122		}
123	
124		ret = write(g_fd[ViPipe], buf, gc2083_addr_byte + gc2083_data_byte);
125		if (ret < 0) {
126			CVI_TRACE_SNS(CVI_DBG_ERR, "I2C_WRITE error!\n");
127			return CVI_FAILURE;
128		}
129		ret = read(g_fd[ViPipe], buf, gc2083_addr_byte + gc2083_data_byte);
130		//syslog(LOG_DEBUG, "i2c w 0x%x 0x%x\n", addr, data);
131		return CVI_SUCCESS;
132	}
