214	int  gc2083_probe(VI_PIPE ViPipe)
215	{
216		int nVal;
217		int nVal2;
218	
219		usleep(50);
220		if (gc2083_i2c_init(ViPipe) != CVI_SUCCESS)
221			return CVI_FAILURE;
222	
223		nVal  = gc2083_read_register(ViPipe, GC2083_CHIP_ID_ADDR_H);
224		nVal2 = gc2083_read_register(ViPipe, GC2083_CHIP_ID_ADDR_L);
225		if (nVal < 0 || nVal2 < 0) {
226			CVI_TRACE_SNS(CVI_DBG_ERR, "read sensor id error.\n");
227			return nVal;
228		}
229	
230		if ((((nVal & 0xFF) << 8) | (nVal2 & 0xFF)) != GC2083_CHIP_ID) {
231			CVI_TRACE_SNS(CVI_DBG_ERR, "Sensor ID Mismatch! Use the wrong sensor??\n");
232			return CVI_FAILURE;
233		}
234	
235		return CVI_SUCCESS;
236	}
