159	static CVI_S32 cmos_fps_set(VI_PIPE ViPipe, CVI_FLOAT f32Fps, AE_SENSOR_DEFAULT_S *pstAeSnsDft)
160	{
161		ISP_SNS_STATE_S *pstSnsState = CVI_NULL;
162		CVI_U32 u32VMAX;
163		CVI_FLOAT f32MaxFps = 0;
164		CVI_FLOAT f32MinFps = 0;
165		CVI_U32 u32Vts = 0;
166		ISP_SNS_REGS_INFO_S *pstSnsRegsInfo = CVI_NULL;
167	
168		CMOS_CHECK_POINTER(pstAeSnsDft);
169		GC2083_SENSOR_GET_CTX(ViPipe, pstSnsState);
170		CMOS_CHECK_POINTER(pstSnsState);
171	
172		u32Vts = g_astGc2083_mode[pstSnsState->u8ImgMode].u32VtsDef;
173		pstSnsRegsInfo = &pstSnsState->astSyncInfo[0].snsCfg;
174		f32MaxFps = g_astGc2083_mode[pstSnsState->u8ImgMode].f32MaxFps;
175		f32MinFps = g_astGc2083_mode[pstSnsState->u8ImgMode].f32MinFps;
176	
177		if ((f32Fps <= f32MaxFps) && (f32Fps >= f32MinFps)) {
178			u32VMAX = u32Vts * f32MaxFps / DIV_0_TO_1_FLOAT(f32Fps);
179		} else {
180			CVI_TRACE_SNS(CVI_DBG_ERR, "Unsupport Fps: %f\n", f32Fps);
181			return CVI_FAILURE;
182		}
183	
184		u32VMAX = (u32VMAX > GC2083_FULL_LINES_MAX) ? GC2083_FULL_LINES_MAX : u32VMAX;
185		pstSnsRegsInfo->astI2cData[LINEAR_VTS_H].u32Data = ((u32VMAX & 0xFF00) >> 8);
186		pstSnsRegsInfo->astI2cData[LINEAR_VTS_L].u32Data = (u32VMAX & 0xFF);
187	
188	
189		pstSnsState->u32FLStd = u32VMAX;
190	
191		pstAeSnsDft->f32Fps = f32Fps;
192		pstAeSnsDft->u32LinesPer500ms = pstSnsState->u32FLStd * f32Fps / 2;
193		pstAeSnsDft->u32FullLinesStd = pstSnsState->u32FLStd;
194		pstAeSnsDft->u32MaxIntTime = pstSnsState->u32FLStd - 8;
195		pstSnsState->au32FL[0] = pstSnsState->u32FLStd;
196		pstAeSnsDft->u32FullLines = pstSnsState->au32FL[0];
197		pstAeSnsDft->u32HmaxTimes = (1000000) / (pstSnsState->u32FLStd * DIV_0_TO_1_FLOAT(f32Fps));
198	
199		return CVI_SUCCESS;
200	}
