283	static CVI_S32 cmos_again_calc_table(VI_PIPE ViPipe, CVI_U32 *pu32AgainLin, CVI_U32 *pu32AgainDb)
284	{
285		int i, total;
286		CVI_U32 pregain;
287	
288		CMOS_CHECK_POINTER(pu32AgainLin);
289		CMOS_CHECK_POINTER(pu32AgainDb);
290		UNUSED(ViPipe);
291		total = sizeof(gain_table) / sizeof(CVI_U32);
292	
293		if (*pu32AgainLin >= (gain_table[total - 1] * 16)) {
294			*pu32AgainLin = *pu32AgainDb = gain_table[total - 1] * 16;
295			return CVI_SUCCESS;
296		}
297	
298		for (i = 1; i < total; i++) {
299			if (*pu32AgainLin < (gain_table[i] * 16))
300				break;
301		}
302		i--;
303		// find the pregain
304		pregain = *pu32AgainLin * 64 / (gain_table[i] * 16);
305		// set the Db as the AE algo gain, we need this to do gain update
306		*pu32AgainDb = *pu32AgainLin;
307		// set the Lin as the closest sensor gain for AE algo reference
308		*pu32AgainLin = pregain * (gain_table[i] * 16) / 64;
309	
310		return CVI_SUCCESS;
311	}
