319		UNUSED(ViPipe);
320		// find the pregain
321		pregain = *pu32DgainLin * 64 / 1024;
322		// set the Db as the AE algo gain, we need this to do gain update
323		*pu32DgainDb = *pu32DgainLin;
324		// set the Lin as the closest sensor gain for AE algo reference
325		*pu32DgainLin = pregain * 16;
326	
327		return CVI_SUCCESS;
328	}
