330	static CVI_S32 cmos_gains_update(VI_PIPE ViPipe, CVI_U32 *pu32Again, CVI_U32 *pu32Dgain)
331	{
332		ISP_SNS_STATE_S *pstSnsState = CVI_NULL;
333		ISP_SNS_REGS_INFO_S *pstSnsRegsInfo = CVI_NULL;
334		CVI_U32 u32Again;
335		CVI_U32 u32Dgain;
336		int i, total;
337	
338		total = sizeof(gain_table) / sizeof(CVI_U32);
339	
340		GC2083_SENSOR_GET_CTX(ViPipe, pstSnsState);
341		CMOS_CHECK_POINTER(pstSnsState);
342		CMOS_CHECK_POINTER(pu32Again);
343		CMOS_CHECK_POINTER(pu32Dgain);
344		pstSnsRegsInfo = &pstSnsState->astSyncInfo[0].snsCfg;
345	
346		/* only surpport linear mode */
347		u32Again = pu32Again[0];
348		/* To kepp the linearity. we assume AE algo adjusts the dgain only when the again reachs the maximum value */
349		if (u32Again < (9474*16)) {
350			for (i = 1; i < total; i++) {
351				if (*pu32Again < (gain_table[i] * 16))
352					break;
353			}
354			i--;
355			// find the pregain
356			u32Dgain = u32Again * 64 / (gain_table[i] * 16);
357			u32Again = i;
358		} else {
359			// find the pregain
360			u32Dgain = u32Again * 64 / (gain_table[total - 1] * 16);
361			u32Again = total - 1;
362		}
363		// u32Dgain = pu32Dgain[0] * 64 / 1024;
364		if (pstSnsState->enWDRMode == WDR_MODE_NONE) {
365			pstSnsRegsInfo->astI2cData[LINEAR_AGAIN_L].u32Data = regValTable[u32Again][0];
366			pstSnsRegsInfo->astI2cData[LINEAR_AGAIN_HOLD].u32Data = 0X2e;
367			pstSnsRegsInfo->astI2cData[LINEAR_AGAIN_H].u32Data = regValTable[u32Again][1];
368			pstSnsRegsInfo->astI2cData[LINEAR_AGAIN_REL].u32Data = 0X28;
369			pstSnsRegsInfo->astI2cData[LINEAR_COL_AGAIN_H].u32Data = regValTable[u32Again][2];
370			pstSnsRegsInfo->astI2cData[LINEAR_COL_AGAIN_L].u32Data = regValTable[u32Again][3];
371			pstSnsRegsInfo->astI2cData[LINEAR_AGAIN_MAG1].u32Data = regValTable[u32Again][4];
372			pstSnsRegsInfo->astI2cData[LINEAR_AGAIN_MAG2].u32Data = regValTable[u32Again][5];
373			pstSnsRegsInfo->astI2cData[LINEAR_AGAIN_MAG3].u32Data = regValTable[u32Again][6];
374			pstSnsRegsInfo->astI2cData[LINEAR_AGAIN_MAG4].u32Data = regValTable[u32Again][7];
375			pstSnsRegsInfo->astI2cData[LINEAR_AGAIN_MAG5].u32Data = regValTable[u32Again][8];
376			pstSnsRegsInfo->astI2cData[LINEAR_AGAIN_MAG6].u32Data = regValTable[u32Again][9];
377			pstSnsRegsInfo->astI2cData[LINEAR_AGAIN_MAG7].u32Data = regValTable[u32Again][10];
378			pstSnsRegsInfo->astI2cData[LINEAR_AGAIN_MAG8].u32Data = regValTable[u32Again][11];
379			pstSnsRegsInfo->astI2cData[LINEAR_AGAIN_MAG9].u32Data = regValTable[u32Again][12];
380	
381			pstSnsRegsInfo->astI2cData[LINEAR_DGAIN_H].u32Data = (u32Dgain >> 6);
382			pstSnsRegsInfo->astI2cData[LINEAR_DGAIN_L].u32Data = (u32Dgain & 0x3F) << 2;
383		} else {
384			CVI_TRACE_SNS(CVI_DBG_ERR, "This Mode not support!\n");
385		}
386	
387		return CVI_SUCCESS;
388	}
