497	static CVI_U32 sensor_cmp_wdr_size(ISP_SNS_ISP_INFO_S *pstWdr1, ISP_SNS_ISP_INFO_S *pstWdr2)
498	{
499		CVI_U32 i;
500	
501		if (pstWdr1->frm_num != pstWdr2->frm_num)
502			goto _mismatch;
503		for (i = 0; i < 2; i++) {
504			if (pstWdr1->img_size[i].stSnsSize.u32Width != pstWdr2->img_size[i].stSnsSize.u32Width)
505				goto _mismatch;
506			if (pstWdr1->img_size[i].stSnsSize.u32Height != pstWdr2->img_size[i].stSnsSize.u32Height)
507				goto _mismatch;
508			if (pstWdr1->img_size[i].stWndRect.s32X != pstWdr2->img_size[i].stWndRect.s32X)
509				goto _mismatch;
510			if (pstWdr1->img_size[i].stWndRect.s32Y != pstWdr2->img_size[i].stWndRect.s32Y)
511				goto _mismatch;
512			if (pstWdr1->img_size[i].stWndRect.u32Width != pstWdr2->img_size[i].stWndRect.u32Width)
513				goto _mismatch;
514			if (pstWdr1->img_size[i].stWndRect.u32Height != pstWdr2->img_size[i].stWndRect.u32Height)
515				goto _mismatch;
516		}
517	
518		return 0;
519	_mismatch:
520		return 1;
521	}
