523	static CVI_S32 cmos_get_sns_regs_info(VI_PIPE ViPipe, ISP_SNS_SYNC_INFO_S *pstSnsSyncInfo)
524	{
525		CVI_U32 i;
526		ISP_SNS_STATE_S *pstSnsState = CVI_NULL;
527		ISP_SNS_REGS_INFO_S *pstSnsRegsInfo = CVI_NULL;
528		ISP_SNS_SYNC_INFO_S *pstCfg0 = CVI_NULL;
529		ISP_SNS_SYNC_INFO_S *pstCfg1 = CVI_NULL;
530		ISP_I2C_DATA_S *pstI2c_data = CVI_NULL;
531	
532		CMOS_CHECK_POINTER(pstSnsSyncInfo);
533		GC2083_SENSOR_GET_CTX(ViPipe, pstSnsState);
534		CMOS_CHECK_POINTER(pstSnsState);
535		pstSnsRegsInfo = &pstSnsSyncInfo->snsCfg;
536		pstCfg0 = &pstSnsState->astSyncInfo[0];
537		pstCfg1 = &pstSnsState->astSyncInfo[1];
538		pstI2c_data = pstCfg0->snsCfg.astI2cData;
539	
540		if ((pstSnsState->bSyncInit == CVI_FALSE) || (pstSnsRegsInfo->bConfig == CVI_FALSE)) {
541			pstCfg0->snsCfg.enSnsType = SNS_I2C_TYPE;
542			pstCfg0->snsCfg.unComBus.s8I2cDev = g_aunGc2083_BusInfo[ViPipe].s8I2cDev;
543			pstCfg0->snsCfg.u8Cfg2ValidDelayMax = 0;
544			pstCfg0->snsCfg.use_snsr_sram = CVI_TRUE;
545			pstCfg0->snsCfg.u32RegNum = LINEAR_REGS_NUM;
546	
547			for (i = 0; i < pstCfg0->snsCfg.u32RegNum; i++) {
548				pstI2c_data[i].bUpdate = CVI_TRUE;
549				pstI2c_data[i].u8DevAddr = gc2083_i2c_addr;
550				pstI2c_data[i].u32AddrByteNum = gc2083_addr_byte;
551				pstI2c_data[i].u32DataByteNum = gc2083_data_byte;
552			}
553	
554			switch (pstSnsState->enWDRMode) {
555			default:
556				pstI2c_data[LINEAR_EXP_H].u32RegAddr = GC2083_EXP_H_ADDR;
557				pstI2c_data[LINEAR_EXP_L].u32RegAddr = GC2083_EXP_L_ADDR;
558				pstI2c_data[LINEAR_AGAIN_H].u32RegAddr = GC2083_AGAIN_H_ADDR;
559				pstI2c_data[LINEAR_AGAIN_L].u32RegAddr = GC2083_AGAIN_L_ADDR;
560				pstI2c_data[LINEAR_COL_AGAIN_H].u32RegAddr = GC2083_COL_AGAIN_H_ADDR;
561				pstI2c_data[LINEAR_COL_AGAIN_L].u32RegAddr = GC2083_COL_AGAIN_L_ADDR;
562				pstI2c_data[LINEAR_AGAIN_MAG1].u32RegAddr = GC2083_AGAIN_MAG1;
563				pstI2c_data[LINEAR_AGAIN_HOLD].u32RegAddr = GC2083_AGAIN_HOLD;
564				pstI2c_data[LINEAR_AGAIN_MAG2].u32RegAddr = GC2083_AGAIN_MAG2;
565				pstI2c_data[LINEAR_AGAIN_MAG3].u32RegAddr = GC2083_AGAIN_MAG3;
566				pstI2c_data[LINEAR_AGAIN_MAG4].u32RegAddr = GC2083_AGAIN_MAG4;
567				pstI2c_data[LINEAR_AGAIN_MAG5].u32RegAddr = GC2083_AGAIN_MAG5;
568				pstI2c_data[LINEAR_AGAIN_MAG6].u32RegAddr = GC2083_AGAIN_MAG6;
569				pstI2c_data[LINEAR_AGAIN_MAG7].u32RegAddr = GC2083_AGAIN_MAG7;
570				pstI2c_data[LINEAR_AGAIN_MAG8].u32RegAddr = GC2083_AGAIN_MAG8;
571				pstI2c_data[LINEAR_AGAIN_MAG9].u32RegAddr = GC2083_AGAIN_MAG9;
572				pstI2c_data[LINEAR_AGAIN_REL].u32RegAddr = GC2083_AGAIN_HOLD;
573				pstI2c_data[LINEAR_DGAIN_H].u32RegAddr = GC2083_DGAIN_H_ADDR;
574				pstI2c_data[LINEAR_DGAIN_L].u32RegAddr = GC2083_DGAIN_L_ADDR;
575				pstI2c_data[LINEAR_VTS_H].u32RegAddr = GC2083_VTS_H_ADDR;
576				pstI2c_data[LINEAR_VTS_L].u32RegAddr = GC2083_VTS_L_ADDR;
577			}
578			pstSnsState->bSyncInit = CVI_TRUE;
579			pstCfg0->snsCfg.need_update = CVI_TRUE;
580			/* recalcualte WDR size */
581			cmos_get_wdr_size(ViPipe, &pstCfg0->ispCfg);
582			pstCfg0->ispCfg.need_update = CVI_TRUE;
583		} else {
584	
585			CVI_U32 gainsUpdate = 0;
586			CVI_U32 vtsUpdate = 0;
587			CVI_U32 shutterUpdate = 0;
588	
589			pstCfg0->snsCfg.need_update = CVI_FALSE;
590			for (i = 0; i < pstCfg0->snsCfg.u32RegNum; i++) {
591				if (pstCfg0->snsCfg.astI2cData[i].u32Data == pstCfg1->snsCfg.astI2cData[i].u32Data) {
592					pstCfg0->snsCfg.astI2cData[i].bUpdate = CVI_FALSE;
593				} else {
594					if ((i >= LINEAR_AGAIN_L) && (i <= LINEAR_DGAIN_L))
595						gainsUpdate = 1;
596					if ((i >= LINEAR_VTS_H) && (i <= LINEAR_VTS_L))
597						vtsUpdate = 1;
598					if (i <= LINEAR_EXP_L)
599						shutterUpdate = 1;
600	
601					pstCfg0->snsCfg.astI2cData[i].bUpdate = CVI_TRUE;
602					pstCfg0->snsCfg.need_update = CVI_TRUE;
603				}
604			}
605			if (gainsUpdate) {
606				pstCfg0->snsCfg.astI2cData[LINEAR_AGAIN_L].bUpdate = CVI_TRUE;
607				pstCfg0->snsCfg.astI2cData[LINEAR_AGAIN_H].bUpdate = CVI_TRUE;
608				pstCfg0->snsCfg.astI2cData[LINEAR_COL_AGAIN_H].bUpdate = CVI_TRUE;
609				pstCfg0->snsCfg.astI2cData[LINEAR_COL_AGAIN_L].bUpdate = CVI_TRUE;
610				pstCfg0->snsCfg.astI2cData[LINEAR_AGAIN_MAG1].bUpdate = CVI_TRUE;
611				pstCfg0->snsCfg.astI2cData[LINEAR_AGAIN_HOLD].bUpdate = CVI_TRUE;
612				pstCfg0->snsCfg.astI2cData[LINEAR_AGAIN_MAG2].bUpdate = CVI_TRUE;
613				pstCfg0->snsCfg.astI2cData[LINEAR_AGAIN_MAG3].bUpdate = CVI_TRUE;
614				pstCfg0->snsCfg.astI2cData[LINEAR_AGAIN_MAG4].bUpdate = CVI_TRUE;
615				pstCfg0->snsCfg.astI2cData[LINEAR_AGAIN_MAG5].bUpdate = CVI_TRUE;
616				pstCfg0->snsCfg.astI2cData[LINEAR_AGAIN_MAG6].bUpdate = CVI_TRUE;
617				pstCfg0->snsCfg.astI2cData[LINEAR_AGAIN_MAG7].bUpdate = CVI_TRUE;
618				pstCfg0->snsCfg.astI2cData[LINEAR_AGAIN_MAG8].bUpdate = CVI_TRUE;
619				pstCfg0->snsCfg.astI2cData[LINEAR_AGAIN_MAG9].bUpdate = CVI_TRUE;
620				pstCfg0->snsCfg.astI2cData[LINEAR_AGAIN_REL].bUpdate = CVI_TRUE;
621				pstCfg0->snsCfg.astI2cData[LINEAR_DGAIN_H].bUpdate = CVI_TRUE;
622				pstCfg0->snsCfg.astI2cData[LINEAR_DGAIN_L].bUpdate = CVI_TRUE;
623			}
624			if (shutterUpdate) {
625				pstCfg0->snsCfg.astI2cData[LINEAR_EXP_H].bUpdate = CVI_TRUE;
626				pstCfg0->snsCfg.astI2cData[LINEAR_EXP_L].bUpdate = CVI_TRUE;
627			}
628			if (vtsUpdate) {
629				pstCfg0->snsCfg.astI2cData[LINEAR_VTS_H].bUpdate = CVI_TRUE;
630				pstCfg0->snsCfg.astI2cData[LINEAR_VTS_L].bUpdate = CVI_TRUE;
631			}
632	
633			/* check update isp crop or not */
634			pstCfg0->ispCfg.need_update = (sensor_cmp_wdr_size(&pstCfg0->ispCfg, &pstCfg1->ispCfg) ?
635					CVI_TRUE : CVI_FALSE);
636		}
637	
638		pstSnsRegsInfo->bConfig = CVI_FALSE;
639		memcpy(pstSnsSyncInfo, &pstSnsState->astSyncInfo[0], sizeof(ISP_SNS_SYNC_INFO_S));
640		memcpy(&pstSnsState->astSyncInfo[1], &pstSnsState->astSyncInfo[0], sizeof(ISP_SNS_SYNC_INFO_S));
641		pstSnsState->au32FL[1] = pstSnsState->au32FL[0];
642	
643		return CVI_SUCCESS;
644	}
