646	static CVI_S32 cmos_set_image_mode(VI_PIPE ViPipe, ISP_CMOS_SENSOR_IMAGE_MODE_S *pstSensorImageMode)
647	{
648		CVI_U8 u8SensorImageMode = 0;
649		ISP_SNS_STATE_S *pstSnsState = CVI_NULL;
650	
651		CMOS_CHECK_POINTER(pstSensorImageMode);
652		GC2083_SENSOR_GET_CTX(ViPipe, pstSnsState);
653		CMOS_CHECK_POINTER(pstSnsState);
654	
655		u8SensorImageMode = pstSnsState->u8ImgMode;
656		pstSnsState->bSyncInit = CVI_FALSE;
657	
658		if (pstSensorImageMode->f32Fps <= 30) {
659			if (pstSnsState->enWDRMode == WDR_MODE_NONE) {
660				if (GC2083_RES_IS_1080P(pstSensorImageMode->u16Width, pstSensorImageMode->u16Height))
661					u8SensorImageMode = GC2083_MODE_1920X1080P30;
662				else {
663					CVI_TRACE_SNS(CVI_DBG_ERR, "Not support! Width:%d, Height:%d, Fps:%f, WDRMode:%d\n",
664						      pstSensorImageMode->u16Width,
665						      pstSensorImageMode->u16Height,
666						      pstSensorImageMode->f32Fps,
667						      pstSnsState->enWDRMode);
668					return CVI_FAILURE;
669				}
670			} else {
671				CVI_TRACE_SNS(CVI_DBG_ERR, "Not support! Width:%d, Height:%d, Fps:%f, WDRMode:%d\n",
672					      pstSensorImageMode->u16Width,
673					      pstSensorImageMode->u16Height,
674					      pstSensorImageMode->f32Fps,
675					      pstSnsState->enWDRMode);
676				return CVI_FAILURE;
677			}
678		} else {
679			CVI_TRACE_SNS(CVI_DBG_ERR, "Not support this Fps:%f\n", pstSensorImageMode->f32Fps);
680			return CVI_FAILURE;
681		}
682	
683		if ((pstSnsState->bInit == CVI_TRUE) && (u8SensorImageMode == pstSnsState->u8ImgMode)) {
684			/* Don't need to switch SensorImageMode */
685			return CVI_FAILURE;
686		}
687	
688		pstSnsState->u8ImgMode = u8SensorImageMode;
689	
690		return CVI_SUCCESS;
691	}
