812	static CVI_S32 sensor_ctx_init(VI_PIPE ViPipe)
813	{
814		ISP_SNS_STATE_S *pastSnsStateCtx = CVI_NULL;
815	
816		GC2083_SENSOR_GET_CTX(ViPipe, pastSnsStateCtx);
817	
818		if (pastSnsStateCtx == CVI_NULL) {
819			pastSnsStateCtx = (ISP_SNS_STATE_S *)malloc(sizeof(ISP_SNS_STATE_S));
820			if (pastSnsStateCtx == CVI_NULL) {
821				CVI_TRACE_SNS(CVI_DBG_ERR, "Isp[%d] SnsCtx malloc memory failed!\n", ViPipe);
822				return -ENOMEM;
823			}
824		}
825	
826		memset(pastSnsStateCtx, 0, sizeof(ISP_SNS_STATE_S));
827	
828		GC2083_SENSOR_SET_CTX(ViPipe, pastSnsStateCtx);
829	
830		return CVI_SUCCESS;
831	}
832	
833	static CVI_VOID sensor_ctx_exit(VI_PIPE ViPipe)
834	{
835		ISP_SNS_STATE_S *pastSnsStateCtx = CVI_NULL;
836	
837		GC2083_SENSOR_GET_CTX(ViPipe, pastSnsStateCtx);
838		SENSOR_FREE(pastSnsStateCtx);
839		GC2083_SENSOR_RESET_CTX(ViPipe);
840	}
