842	static CVI_S32 sensor_register_callback(VI_PIPE ViPipe, ALG_LIB_S *pstAeLib, ALG_LIB_S *pstAwbLib)
843	{
844		CVI_S32 s32Ret;
845		ISP_SENSOR_REGISTER_S stIspRegister;
846		AE_SENSOR_REGISTER_S  stAeRegister;
847		AWB_SENSOR_REGISTER_S stAwbRegister;
848		ISP_SNS_ATTR_INFO_S   stSnsAttrInfo;
849	
850		CMOS_CHECK_POINTER(pstAeLib);
851		CMOS_CHECK_POINTER(pstAwbLib);
852	
853		s32Ret = sensor_ctx_init(ViPipe);
854	
855		if (s32Ret != CVI_SUCCESS)
856			return CVI_FAILURE;
857	
858		stSnsAttrInfo.eSensorId = GC2083_ID;
859	
860		s32Ret  = cmos_init_sensor_exp_function(&stIspRegister.stSnsExp);
861		s32Ret |= CVI_ISP_SensorRegCallBack(ViPipe, &stSnsAttrInfo, &stIspRegister);
862	
863		if (s32Ret != CVI_SUCCESS) {
864			CVI_TRACE_SNS(CVI_DBG_ERR, "sensor register callback function failed!\n");
865			return s32Ret;
866		}
867	
868		s32Ret  = cmos_init_ae_exp_function(&stAeRegister.stAeExp);
869		s32Ret |= CVI_AE_SensorRegCallBack(ViPipe, pstAeLib, &stSnsAttrInfo, &stAeRegister);
870	
871		if (s32Ret != CVI_SUCCESS) {
872			CVI_TRACE_SNS(CVI_DBG_ERR, "sensor register callback function to ae lib failed!\n");
873			return s32Ret;
874		}
875	
876		s32Ret  = cmos_init_awb_exp_function(&stAwbRegister.stAwbExp);
877		s32Ret |= CVI_AWB_SensorRegCallBack(ViPipe, pstAwbLib, &stSnsAttrInfo, &stAwbRegister);
878	
879		if (s32Ret != CVI_SUCCESS) {
880			CVI_TRACE_SNS(CVI_DBG_ERR, "sensor register callback function to awb lib failed!\n");
881			return s32Ret;
882		}
883	
884		return CVI_SUCCESS;
885	}
886	
887	static CVI_S32 sensor_unregister_callback(VI_PIPE ViPipe, ALG_LIB_S *pstAeLib, ALG_LIB_S *pstAwbLib)
888	{
889		CVI_S32 s32Ret;
890	
891		CMOS_CHECK_POINTER(pstAeLib);
892		CMOS_CHECK_POINTER(pstAwbLib);
893	
894		s32Ret = CVI_ISP_SensorUnRegCallBack(ViPipe, GC2083_ID);
895		if (s32Ret != CVI_SUCCESS) {
896			CVI_TRACE_SNS(CVI_DBG_ERR, "sensor unregister callback function failed!\n");
897			return s32Ret;
898		}
899	
900		s32Ret = CVI_AE_SensorUnRegCallBack(ViPipe, pstAeLib, GC2083_ID);
901		if (s32Ret != CVI_SUCCESS) {
902			CVI_TRACE_SNS(CVI_DBG_ERR, "sensor unregister callback function to ae lib failed!\n");
903			return s32Ret;
904		}
905	
906		s32Ret = CVI_AWB_SensorUnRegCallBack(ViPipe, pstAwbLib, GC2083_ID);
907		if (s32Ret != CVI_SUCCESS) {
908			CVI_TRACE_SNS(CVI_DBG_ERR, "sensor unregister callback function to awb lib failed!\n");
909			return s32Ret;
910		}
911	
912		sensor_ctx_exit(ViPipe);
913	
914		return CVI_SUCCESS;
915	}
