219	static void i2c_dw_xfer_init(struct dw_i2c_dev *dev)
220	{
221		struct i2c_msg *msgs = dev->msgs;
222		u32 ic_con = 0, ic_tar = 0;
223		u32 dummy;
224	
225		/* Disable the adapter */
226		__i2c_dw_disable(dev);
227	
228		/* If the slave address is ten bit address, enable 10BITADDR */
229		if (msgs[dev->msg_write_idx].flags & I2C_M_TEN) {
230			ic_con = DW_IC_CON_10BITADDR_MASTER;
231			/*
232			 * If I2C_DYNAMIC_TAR_UPDATE is set, the 10-bit addressing
233			 * mode has to be enabled via bit 12 of IC_TAR register.
234			 * We set it always as I2C_DYNAMIC_TAR_UPDATE can't be
235			 * detected from registers.
236			 */
237			ic_tar = DW_IC_TAR_10BITADDR_MASTER;
238		}
239	
240		regmap_update_bits(dev->map, DW_IC_CON, DW_IC_CON_10BITADDR_MASTER,
241				   ic_con);
242	
243		/*
244		 * Set the slave (target) address and enable 10-bit addressing mode
245		 * if applicable.
246		 */
247		regmap_write(dev->map, DW_IC_TAR,
248			     msgs[dev->msg_write_idx].addr | ic_tar);
249	
250		/* Enforce disabled interrupts (due to HW issues) */
251		i2c_dw_disable_int(dev);
252	
253		/* Enable the adapter */
254		__i2c_dw_enable(dev);
255	
256		/* Dummy read to avoid the register getting stuck on Bay Trail */
257		regmap_read(dev->map, DW_IC_ENABLE_STATUS, &dummy);
258	
259		/* Clear and enable interrupts */
260		regmap_read(dev->map, DW_IC_CLR_INTR, &dummy);
261		regmap_write(dev->map, DW_IC_INTR_MASK, DW_IC_INTR_MASTER_MASK);
262	}
