### 3. I2C 控制器配置

**文件：** `linux_5.10/drivers/i2c/busses/i2c-designware-master.c`

#### 3.1 配置 I2C 模式

```c
void i2c_dw_configure_master(struct dw_i2c_dev *dev)
{
    struct i2c_timings *t = &dev->timings;

    dev->functionality = I2C_FUNC_10BIT_ADDR | DW_IC_DEFAULT_FUNCTIONALITY;

    // 配置主模式
    dev->master_cfg = DW_IC_CON_MASTER | DW_IC_CON_SLAVE_DISABLE |
                      DW_IC_CON_RESTART_EN;

    dev->mode = DW_IC_MASTER;

    // 配置速度模式
    switch (t->bus_freq_hz) {
    case I2C_MAX_STANDARD_MODE_FREQ:    // 100kHz
        dev->master_cfg |= DW_IC_CON_SPEED_STD;
        break;
    case I2C_MAX_HIGH_SPEED_MODE_FREQ:  // 3.4MHz
        dev->master_cfg |= DW_IC_CON_SPEED_HIGH;
        break;
    default:                            // 400kHz
        dev->master_cfg |= DW_IC_CON_SPEED_FAST;
    }
}
```

#### 3.2 计算 SCL 时序参数

```c
static int i2c_dw_set_timings_master(struct dw_i2c_dev *dev)
{
    u32 ic_clk;
    struct i2c_timings *t = &dev->timings;
    u32 sda_falling_time = t->sda_fall_ns ?: 300;  // 默认 300ns
    u32 scl_falling_time = t->scl_fall_ns ?: 300;  // 默认 300ns

    // 计算标准模式 (100kHz) 时序参数
    if (!dev->ss_hcnt || !dev->ss_lcnt) {
        ic_clk = i2c_dw_clk_rate(dev);  // 获取时钟频率 (25MHz)

        // HCNT: SCL 高电平时间
        // tHIGH = 4.0us, tf = 300ns
        dev->ss_hcnt = i2c_dw_scl_hcnt(ic_clk, 4000, sda_falling_time, 0, 0);

        // LCNT: SCL 低电平时间
        // tLOW = 4.7us, tf = 300ns
        dev->ss_lcnt = i2c_dw_scl_lcnt(ic_clk, 4700, scl_falling_time, 0);
    }

    // 计算快速模式 (400kHz) 时序参数
    if (!dev->fs_hcnt || !dev->fs_lcnt) {
        ic_clk = i2c_dw_clk_rate(dev);

        // HCNT: SCL 高电平时间
        // tHIGH = 0.6us, tf = 300ns
        dev->fs_hcnt = i2c_dw_scl_hcnt(ic_clk, 600, sda_falling_time, 0, 0);

        // LCNT: SCL 低电平时间
        // tLOW = 1.3us, tf = 300ns
        dev->fs_lcnt = i2c_dw_scl_lcnt(ic_clk, 1300, scl_falling_time, 0);
    }
}
```

#### 3.3 初始化 I2C 控制器

```c
static int i2c_dw_init_master(struct dw_i2c_dev *dev)
{
    int ret;

    ret = i2c_dw_acquire_lock(dev);
    if (ret)
        return ret;

    /* 禁用适配器 */
    __i2c_dw_disable(dev);

    /* 写入标准速度时序参数 */
    regmap_write(dev->map, DW_IC_SS_SCL_HCNT, dev->ss_hcnt);
    regmap_write(dev->map, DW_IC_SS_SCL_LCNT, dev->ss_lcnt);

    /* 写入快速模式时序参数 */
    regmap_write(dev->map, DW_IC_FS_SCL_HCNT, dev->fs_hcnt);
    regmap_write(dev->map, DW_IC_FS_SCL_LCNT, dev->fs_lcnt);

    /* 写入 SDA 保持时间 */
    dev->sda_hold_time = 0x1E;  // 默认值
    if (dev->sda_hold_time)
        regmap_write(dev->map, DW_IC_SDA_HOLD, dev->sda_hold_time);

    /* 配置 FIFO */
    i2c_dw_configure_fifo_master(dev);

    i2c_dw_release_lock(dev);

    return 0;
}

static void i2c_dw_configure_fifo_master(struct dw_i2c_dev *dev)
{
    /* 设置 TX FIFO 阈值 */
    regmap_write(dev->map, DW_IC_TX_TL, 0);

    /* 设置 RX FIFO 阈值 */
    regmap_write(dev->map, DW_IC_RX_TL, 0);

    /* 写入配置寄存器 */
    regmap_write(dev->map, DW_IC_CON, dev->master_cfg);
}
```

#### 3.4 使能 I2C 控制器

```c
// 文件: linux_5.10/drivers/i2c/busses/i2c-designware-core.h

static inline void __i2c_dw_enable(struct dw_i2c_dev *dev)
{
    // 写入 1 到 DW_IC_ENABLE 寄存器使能 I2C 控制器
    regmap_write(dev->map, DW_IC_ENABLE, 1);
}

static inline void __i2c_dw_disable_nowait(struct dw_i2c_dev *dev)
{
    // 写入 0 到 DW_IC_ENABLE 寄存器禁用 I2C 控制器
    regmap_write(dev->map, DW_IC_ENABLE, 0);
}
```

### 4. 读取芯片 ID 流程

**文件：** `linux_5.10/drivers/i2c/busses/i2c-designware-master.c`

#### 4.1 设置目标地址并使能

```c
static void i2c_dw_xfer_init(struct dw_i2c_dev *dev)
{
    struct i2c_msg *msgs = dev->msgs;
    u32 ic_con = 0, ic_tar = 0;
    u32 dummy;

    /* 禁用适配器 */
    __i2c_dw_disable(dev);

    /* 如果是 10 位地址，启用 10BITADDR */
    if (msgs[dev->msg_write_idx].flags & I2C_M_TEN) {
        ic_con = DW_IC_CON_10BITADDR_MASTER;
        ic_tar = DW_IC_TAR_10BITADDR_MASTER;
    }

    /* 更新配置寄存器 */
    regmap_update_bits(dev->map, DW_IC_CON, DW_IC_CON_10BITADDR_MASTER, ic_con);

    /* 设置目标地址 (GC2083: 0x37) */
    regmap_write(dev->map, DW_IC_TAR, msgs[dev->msg_write_idx].addr | ic_tar);

    /* 禁用中断 */
    i2c_dw_disable_int(dev);

    /* 使能适配器 */
    __i2c_dw_enable(dev);

    /* 读取使能状态寄存器 (避免 Bay Trail 平台问题) */
    regmap_read(dev->map, DW_IC_ENABLE_STATUS, &dummy);

    /* 清除并使能中断 */
    regmap_read(dev->map, DW_IC_CLR_INTR, &dummy);
    regmap_write(dev->map, DW_IC_INTR_MASK, DW_IC_INTR_MASTER_MASK);
}
```

#### 4.2 发送数据（寄存器地址）

```c
static void i2c_dw_xfer_msg(struct dw_i2c_dev *dev)
{
    struct i2c_msg *msgs = dev->msgs;
    u32 intr_mask;
    int tx_limit, rx_limit;
    u32 buf_len = dev->tx_buf_len;
    u8 *buf = dev->tx_buf;

    intr_mask = DW_IC_INTR_MASTER_MASK;

    // 发送寄存器地址 (2字节)
    while (buf_len > 0 && tx_limit > 0 && rx_limit > 0) {
        u32 cmd = 0;

        // 设置写命令
        cmd |= DW_IC_CMD_WRITE;

        // 写入数据到 TX FIFO
        regmap_write(dev->map, DW_IC_DATA_CMD, cmd | *buf++);

        buf_len--;
        tx_limit--;
    }
}
```

#### 4.3 读取数据

```c
// 读取数据时，需要发送读命令
static void i2c_dw_xfer_msg(struct dw_i2c_dev *dev)
{
    // ...

    // 发送读命令
    u32 cmd = DW_IC_CMD_READ;

    // 如果是最后一个字节，设置停止位
    if (is_last_msg)
        cmd |= DW_IC_CMD_STOP;

    // 写入读命令到 TX FIFO
    regmap_write(dev->map, DW_IC_DATA_CMD, cmd);

    // 等待 RX FIFO 中的数据
    // 数据通过中断处理程序读取
}
```

### 5. I2C 寄存器定义

**文件：** `linux_5.10/drivers/i2c/busses/i2c-designware-core.h`

```c
// 控制寄存器
#define DW_IC_CON           0x00
#define DW_IC_CON_MASTER        0x1      // 主模式
#define DW_IC_CON_SPEED_STD     0x2      // 标准模式 (100kHz)
#define DW_IC_CON_SPEED_FAST    0x4      // 快速模式 (400kHz)
#define DW_IC_CON_SPEED_HIGH    0x6      // 高速模式 (3.4MHz)
#define DW_IC_CON_RESTART_EN    0x20     // 使能重复起始
#define DW_IC_CON_SLAVE_DISABLE 0x40     // 禁用从模式

// 目标地址寄存器
#define DW_IC_TAR           0x04

// 数据命令寄存器
#define DW_IC_DATA_CMD      0x10
#define DW_IC_CMD_READ      0x100       // 读命令
#define DW_IC_CMD_WRITE     0x000       // 写命令
#define DW_IC_CMD_STOP      0x200       // 停止位

// SCL 时序寄存器
#define DW_IC_SS_SCL_HCNT   0x14        // 标准模式 SCL 高电平计数
#define DW_IC_SS_SCL_LCNT   0x18        // 标准模式 SCL 低电平计数
#define DW_IC_FS_SCL_HCNT   0x1C        // 快速模式 SCL 高电平计数
#define DW_IC_FS_SCL_LCNT   0x20        // 快速模式 SCL 低电平计数

// SDA 保持时间寄存器
#define DW_IC_SDA_HOLD      0x7C

// 使能寄存器
#define DW_IC_ENABLE        0x6C
#define DW_IC_ENABLE_STATUS 0x9C

// 状态寄存器
#define DW_IC_STATUS        0x70
#define DW_IC_STATUS_ACTIVITY BIT(0)    // I2C 活动状态

// 中断寄存器
#define DW_IC_INTR_STAT     0x2C
#define DW_IC_INTR_MASK     0x30
#define DW_IC_CLR_INTR      0x40
