## 三、完整底层流程示例

```c
// 最小化 I2C 初始化和读取芯片 ID 底层流程

#include <linux/io.h>
#include <linux/delay.h>

// I2C 寄存器基地址 (I2C2: 0x04020000)
#define I2C_BASE  0x04020000

// 寄存器偏移
#define IC_CON      0x00
#define IC_TAR      0x04
#define IC_DATA_CMD 0x10
#define IC_SS_SCL_HCNT 0x14
#define IC_SS_SCL_LCNT 0x18
#define IC_FS_SCL_HCNT 0x1C
#define IC_FS_SCL_LCNT 0x20
#define IC_SDA_HOLD 0x7C
#define IC_ENABLE   0x6C
#define IC_STATUS   0x70

// 时钟寄存器
#define CLK_EN_3    0x0300200C  // CLK_I2C 使能
#define DIV_CLK_I2C 0x03002104  // CLK_I2C 分频

void i2c_init(void)
{
    u32 reg;

    // 1. 使能 I2C 时钟
    reg = readl(CLK_EN_3);
    reg |= (1 << 7);  // 使能 CLK_I2C
    writel(reg, CLK_EN_3);

    // 2. 设置 I2C 时钟分频 (不分频)
    reg = readl(DIV_CLK_I2C);
    reg &= ~(0xF << 16);  // 清除分频位
    reg |= (1 << 16);     // 分频系数 = 1
    writel(reg, DIV_CLK_I2C);

    // 3. 解除 I2C 复位 (需要平台特定代码)
    // reset_control_deassert(rst);

    // 4. 禁用 I2C 控制器
    writel(0, I2C_BASE + IC_ENABLE);

    // 5. 配置 I2C 模式 (主模式, 标准速度)
    reg = 0x1;      // DW_IC_CON_MASTER
    reg |= 0x2;     // DW_IC_CON_SPEED_STD (100kHz)
    reg |= 0x20;    // DW_IC_CON_RESTART_EN
    reg |= 0x40;    // DW_IC_CON_SLAVE_DISABLE
    writel(reg, I2C_BASE + IC_CON);

    // 6. 配置 SCL 时序 (假设 I2C 时钟 = 25MHz)
    // 标准模式: tHIGH = 4.0us, tLOW = 4.7us
    // HCNT = (25MHz * 4.0us) = 100
    // LCNT = (25MHz * 4.7us) = 117.5 ≈ 118
    writel(100, I2C_BASE + IC_SS_SCL_HCNT);
    writel(118, I2C_BASE + IC_SS_SCL_LCNT);

    // 快速模式: tHIGH = 0.6us, tLOW = 1.3us
    // HCNT = (25MHz * 0.6us) = 15
    // LCNT = (25MHz * 1.3us) = 32.5 ≈ 33
    writel(15, I2C_BASE + IC_FS_SCL_HCNT);
    writel(33, I2C_BASE + IC_FS_SCL_LCNT);

    // 7. 配置 SDA 保持时间
    writel(0x1E, I2C_BASE + IC_SDA_HOLD);  // 30 个时钟周期

    // 8. 使能 I2C 控制器
    writel(1, I2C_BASE + IC_ENABLE);
}

u16 read_chip_id(void)
{
    u32 reg;
    u8 id_h, id_l;

    // 1. 禁用 I2C 控制器
    writel(0, I2C_BASE + IC_ENABLE);

    // 2. 设置目标地址 (GC2083: 0x37)
    writel(0x37, I2C_BASE + IC_TAR);

    // 3. 使能 I2C 控制器
    writel(1, I2C_BASE + IC_ENABLE);

    // 4. 读取芯片 ID 高字节 (0x03F0)
    // 发送寄存器地址高字节
    writel(0x03, I2C_BASE + IC_DATA_CMD);  // 写命令

    // 发送寄存器地址低字节
    writel(0xF0, I2C_BASE + IC_DATA_CMD);  // 写命令

    // 发送读命令
    writel(0x100 | 0x200, I2C_BASE + IC_DATA_CMD);  // 读命令 + 停止位

    // 等待数据接收
    while (!(readl(I2C_BASE + IC_STATUS) & 0x08))  // RX FIFO 非空
        ;

    // 读取数据
    id_h = readl(I2C_BASE + IC_DATA_CMD) & 0xFF;

    // 5. 读取芯片 ID 低字节 (0x03F1)
    // 发送寄存器地址高字节
    writel(0x03, I2C_BASE + IC_DATA_CMD);  // 写命令

    // 发送寄存器地址低字节
    writel(0xF1, I2C_BASE + IC_DATA_CMD);  // 写命令

    // 发送读命令
    writel(0x100 | 0x200, I2C_BASE + IC_DATA_CMD);  // 读命令 + 停止位

    // 等待数据接收
    while (!(readl(I2C_BASE + IC_STATUS) & 0x08))  // RX FIFO 非空
        ;

    // 读取数据
    id_l = readl(I2C_BASE + IC_DATA_CMD) & 0xFF;

    // 6. 返回芯片 ID
    return (id_h << 8) | id_l;  // 期望值: 0x2083
}
